    gr.addColorStop(0, this._rgba(this.pal[1], 0.28 + this.beat * 0.25)); gr.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = gr; ctx.fillRect(0, 0, w, h);
