      ctx.beginPath(); ctx.moveTo(cx + Math.cos(a) * R, cy + Math.sin(a) * R); ctx.lineTo(cx + Math.cos(a) * (R + h * 0.05), cy + Math.sin(a) * (R + h * 0.05)); ctx.stroke();
      ctx.fillStyle = p >= red ? '#c4271c' : '#2b2416';
