          // as _invalidateArtwork — radio proxy URLs are stable but content changes).
          this._confirmedArtUrls = new Map();
          this._failedArtUrls    = new Set();
          const _mainImg = this.shadowRoot?.getElementById('albumImg');
          const _miniImg = this.shadowRoot?.getElementById('miniImg');
          if (_mainImg) { _mainImg.dataset.errorSrc = ''; _mainImg.removeAttribute('src'); }
          if (_miniImg) { _miniImg.dataset.errorSrc = ''; _miniImg.removeAttribute('src'); }
