    if (isPlaying && itunesCacheKey && !(itunesCacheKey in this._itunesArtCache) && !this._isLiveStream(state) && this._config?.itunes_art !== false) {
      this._fetchItunesArt(itunesArtist, itunesAlbum, itunesTrack);
    }

