    const cachedItunes = (this._config?.itunes_art !== false && !this._isLiveStream(state) && itunesCacheKey && this._itunesArtCache[itunesCacheKey]) || null;

    // In-flight: key present with null value (fetch dispatched), OR key absent
    // but we have track metadata (first render before fetch fires).
