      ctx.beginPath(); ctx.moveTo(0.22 * L, 0.05 * L); ctx.quadraticCurveTo(0.14 * L, 0.12 * L, 0.08 * L, 0.15 * L); ctx.quadraticCurveTo(0.12 * L, 0.08 * L, 0.12 * L, 0.06 * L); ctx.closePath(); ctx.fill();
