      ctx.beginPath(); ctx.moveTo(0.32 * L, -0.075 * L); ctx.bezierCurveTo(0.15 * L, -0.11 * L, -0.1 * L, -0.1 * L, -0.3 * L, -0.05 * L); ctx.stroke();
