  _swClose() {
    const o = this._swOpen;
    this._swOpen = null;
    if (o && o._swPlace) o._swPlace(0, true);
  }

  // keep a menu that's just opened wholly inside the card and the screen
  _swFitMenu() {
    const r = this.shadowRoot, host = r?.host;
    if (!host) return;
    const menus = [...r.querySelectorAll('.enqueue-menu, .queue-dropdown-menu')];
    const menu = menus[menus.length - 1];
    if (!menu) return;
    const hr = host.getBoundingClientRect(), pad = 8;
    const bottom = Math.min(hr.bottom, window.innerHeight) - pad, top = Math.max(hr.top, 0) + pad;
    const left = Math.max(hr.left, 0) + pad, right = Math.min(hr.right, window.innerWidth) - pad;
    // menus open with a little scale from their top corner, so the full size comes from offsetWidth/Height
    const box = () => { const b = menu.getBoundingClientRect(); return { top: b.top, right: b.right, bottom: b.top + menu.offsetHeight, left: b.right - menu.offsetWidth }; };
    let mr = box();
    if (menu.offsetHeight > bottom - top) { menu.style.maxHeight = (bottom - top) + 'px'; menu.style.overflowY = 'auto'; mr = box(); }
    const cur = parseFloat(menu.style.top) || 0;
    if (mr.bottom > bottom) menu.style.top = (cur - (mr.bottom - bottom)) + 'px';
    else if (mr.top < top) menu.style.top = (cur + (top - mr.top)) + 'px';
    if (mr.left < left || mr.right > right) {
      menu.style.left = 'auto';
      menu.style.right = (hr.right - right) + 'px';
    }
  }

  // Is a row menu open? A menu left behind in a popup that's since been hidden doesn't count
  // (it can't be seen or tapped away): it's tidied up, so swipes keep working.
  _swMenuOpen() {
    const r = this.shadowRoot;
    if (!r) return false;
    let open = false;
    r.querySelectorAll('.enqueue-backdrop, .queue-dropdown-backdrop, #rpMenuBackdrop').forEach(b => {
      const pop = b.closest('.ma-popup, .info-popup');
      if (!pop || pop.classList.contains('visible')) { open = true; return; }
      pop.querySelectorAll(':scope > .queue-dropdown-menu, :scope > .enqueue-menu').forEach(m => m.remove());
      b.remove();
    });
    return open;
  }

