    const fixed = { add: 'Add to Queue', next: 'Play Next', move_top: 'Move to Top', more_info: 'Info', copy_link: 'Share', share: 'Share', artist_radio: 'Radio', more: 'More' };
    if (/^browse /i.test(t)) return t.replace(/^browse /i, '');
    if (/^(un)?pin\b/i.test(t)) return t.split(/\s+/)[0];
    if (/remove/i.test(id) || /^remove/i.test(t)) return 'Remove';
    if (fixed[id] && (t.length > 12 || !t)) return fixed[id];
    if (id === 'more_info' && /^more info$/i.test(t)) return 'Info';
    return t || fixed[id] || id;
