    var typeOrder  = ['tracks', 'track', 'albums', 'album', 'artists', 'artist', 'playlists', 'playlist', 'radio'];
    var typeToTab  = { tracks: 'track', albums: 'album', artists: 'artist', playlists: 'playlist', radio: 'radio', track: 'track', album: 'album', artist: 'artist', playlist: 'playlist' };

    var availableTypes = typeOrder.filter(function(t) { return grouped[t] && grouped[t].length > 0; });
    Object.keys(grouped).forEach(function(k) {
      if (availableTypes.indexOf(k) === -1 && grouped[k] && grouped[k].length > 0) availableTypes.push(k);
    });

